        .as_millis() as i64;

    let is_terminal = matches!(state, "finished" | "error" | "aborted");

    if is_terminal {
        self.conn.execute(
            "UPDATE profiling_sessions SET state = ?1, ended_at = ?2 WHERE id = ?3",
            params![state, now, id],
        )?;
    } else {
        self.conn.execute(
            "UPDATE profiling_sessions SET state = ?1 WHERE id = ?2",
            params![state, id],
        )?;
    }
    Ok(())
}

pub fn update_state(&self, id: &str, state: &str) -> Result<()> {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as i64;

    let is_terminal = matches!(state, "finished" | "error" | "aborted");

    if is_terminal {
        self.conn.execute(
            "UPDATE sessions SET state = ?1, updated_at = ?2, ended_at = ?3 WHERE id = ?4",
            params![state, now, now, id],
        )?;
    } else {
        self.conn.execute(
            "UPDATE sessions SET state = ?1, updated_at = ?2 WHERE id = ?3",
            params![state, now, id],
        )?;
    }
    Ok(())
}

pub(crate) fn encode_cset(operands: &[Operand]) -> Result<EncodeResult, String> {
    // CSET Rd, cond -> CSINC Rd, XZR, XZR, invert(cond)
    let (rd, is_64) = get_reg(operands, 0)?;
    let cond = match operands.get(1) {
        Some(Operand::Cond(c)) => encode_cond(c).ok_or("invalid cond")?,
        _ => return Err("cset requires condition".to_string()),
    };
    let sf = sf_bit(is_64);
    let inv_cond = cond ^ 1; // invert least significant bit
    let word = (sf << 31) | (0b11010100 << 21)
        | (0b11111 << 16) | (inv_cond << 12) | (0b01 << 10) | (0b11111 << 5) | rd;
    Ok(EncodeResult::Word(word))
}

