pub(super) fn emit_i128_neg_impl(&mut self) {
    self.state.emit("    mvn x0, x0");
    self.state.emit("    mvn x1, x1");
    self.state.emit("    adds x0, x0, #1");
    self.state.emit("    adc x1, x1, xzr");
}

