pub(super) fn emit_int_cmp_impl(&mut self, dest: &Value, op: IrCmpOp, lhs: &Operand, rhs: &Operand, _ty: IrType) {
    self.operand_to_eax(lhs);
    self.operand_to_ecx(rhs);
    self.state.emit("    cmpl %ecx, %eax");

    let set_instr = match op {
        IrCmpOp::Eq => "sete",
        IrCmpOp::Ne => "setne",
        IrCmpOp::Slt => "setl",
        IrCmpOp::Sle => "setle",
        IrCmpOp::Sgt => "setg",
        IrCmpOp::Sge => "setge",
        IrCmpOp::Ult => "setb",
        IrCmpOp::Ule => "setbe",
        IrCmpOp::Ugt => "seta",
        IrCmpOp::Uge => "setae",
    };
    emit!(self.state, "    {} %al", set_instr);
    self.state.emit("    movzbl %al, %eax");
    self.state.reg_cache.invalidate_acc();
    self.store_eax_to(dest);
}

pub(super) fn emit_int_cmp_impl(&mut self, dest: &Value, op: IrCmpOp, lhs: &Operand, rhs: &Operand, ty: IrType) {
    let use_32bit = ty == IrType::I32 || ty == IrType::U32;
    self.emit_int_cmp_insn_typed(lhs, rhs, use_32bit);

    let set_instr = match op {
        IrCmpOp::Eq => "sete",
        IrCmpOp::Ne => "setne",
        IrCmpOp::Slt => "setl",
        IrCmpOp::Sle => "setle",
        IrCmpOp::Sgt => "setg",
        IrCmpOp::Sge => "setge",
        IrCmpOp::Ult => "setb",
        IrCmpOp::Ule => "setbe",
        IrCmpOp::Ugt => "seta",
        IrCmpOp::Uge => "setae",
    };
    self.state.emit_fmt(format_args!("    {} %al", set_instr));
    self.state.emit("    movzbq %al, %rax");
    self.state.reg_cache.invalidate_acc();
    self.store_rax_to(dest);
}

//! Shared utilities for x86 and i686 backends.
//!
//! Both the x86-64 and i686 backends use the same x86 ISA family and share
//! register naming conventions, condition code mappings, and inline assembly
//! template parsing logic. This module provides shared free functions to
//! avoid duplicating these across both backends.

pub(super) fn emit_int_cmp_impl(&mut self, dest: &Value, op: IrCmpOp, lhs: &Operand, rhs: &Operand, _ty: IrType) {
    self.operand_to_eax(lhs);
    self.operand_to_ecx(rhs);
    self.state.emit("    cmpl %ecx, %eax");

    let set_instr = match op {
        IrCmpOp::Eq => "sete",
        IrCmpOp::Ne => "setne",
        IrCmpOp::Slt => "setl",
        IrCmpOp::Sle => "setle",
        IrCmpOp::Sgt => "setg",
        IrCmpOp::Sge => "setge",
        IrCmpOp::Ult => "setb",
        IrCmpOp::Ule => "setbe",
        IrCmpOp::Ugt => "seta",
        IrCmpOp::Uge => "setae",
