    false_label: &str,
) {
    let use_32bit = ty == IrType::I32 || ty == IrType::U32;
    self.emit_int_cmp_insn_typed(lhs, rhs, use_32bit);

    let jcc = match op {
        IrCmpOp::Eq  => "je",
        IrCmpOp::Ne  => "jne",
        IrCmpOp::Slt => "jl",
        IrCmpOp::Sle => "jle",
        IrCmpOp::Sgt => "jg",
