/// Visit all expressions in a statement using a simple closure
///
/// This is a convenience function for cases where you just want to visit
/// all expressions without implementing a full visitor trait.
///
/// # Example
///
/// ```text
/// use vibesql_ast::visitor::visit_expressions;
///
/// let mut count = 0;
/// visit_expressions(&stmt, |expr| {
///     if matches!(expr, Expression::Placeholder(_)) {
///         count += 1;
///     }
/// });
/// ```
pub fn visit_expressions<F>(stmt: &Statement, visitor: F)
where
    F: FnMut(&Expression),
{
    struct ClosureVisitor<F> {
        closure: F,
    }

    impl<F: FnMut(&Expression)> ExpressionVisitor for ClosureVisitor<F> {
        fn pre_visit_expression(&mut self, expr: &Expression) -> VisitResult {
            (self.closure)(expr);
            VisitResult::Continue
        }
    }

    impl<F: FnMut(&Expression)> StatementVisitor for ClosureVisitor<F> {}

    let mut v = ClosureVisitor { closure: visitor };
    walk_statement(&mut v, stmt);
}

/// Visit all expressions in a statement (for counting placeholders)
///
/// This is a convenience wrapper around `vibesql_ast::visitor::walk_statement`
/// that maintains backward compatibility with the existing API.
pub fn visit_statement<F>(stmt: &Statement, visitor: &mut F)
where
    F: FnMut(&Expression),
{
    // Wrap the closure in a struct that implements ExpressionVisitor
    struct ClosureVisitor<'a, F> {
        closure: &'a mut F,
    }

    impl<F: FnMut(&Expression)> ExpressionVisitor for ClosureVisitor<'_, F> {
        fn pre_visit_expression(&mut self, expr: &Expression) -> VisitResult {
            (self.closure)(expr);
            VisitResult::Continue
        }
    }

    impl<F: FnMut(&Expression)> StatementVisitor for ClosureVisitor<'_, F> {}

    let mut v = ClosureVisitor { closure: visitor };
    vibesql_ast::visitor::walk_statement(&mut v, stmt);
}

