        E::BinaryOp { op, left, right } => {
            Some(E::BinaryOp { op: op.clone(), left: map_box(left)?, right: map_box(right)? })
        }

        E::Conjunction(es) => Some(E::Conjunction(map_vec(es)?)),
        E::Disjunction(es) => Some(E::Disjunction(map_vec(es)?)),

