/// Convert string to boolean using SQLite semantics
#[inline(always)]
fn string_to_truthy(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return false;
    }
    // Parse leading numeric portion
    let mut end = 0;
    let mut has_dot = false;
    let mut has_digit = false;
    let chars: Vec<char> = trimmed.chars().collect();
    if !chars.is_empty() && (chars[0] == '-' || chars[0] == '+') {
        end = 1;
    }
    while end < chars.len() {
        let c = chars[end];
        if c.is_ascii_digit() {
            has_digit = true;
            end += 1;
        } else if c == '.' && !has_dot {
            has_dot = true;
            end += 1;
        } else {
            break;
        }
    }
    if !has_digit {
        return false;
    }
    let num_str: String = chars[..end].iter().collect();
    num_str.parse::<f64>().map(|n| n != 0.0).unwrap_or(false)
}

/// Convert string to boolean using SQLite semantics
/// SQLite converts strings to numeric first, then to boolean:
/// - "1x" → 1.0 → true
/// - "0" → 0.0 → false
/// - "" → 0.0 → false
/// - "abc" → 0.0 → false (no leading digits)
#[inline(always)]
fn string_to_truthy(s: &str) -> bool {
    // SQLite behavior: parse leading numeric portion
    // Empty string is falsy
    if s.is_empty() {
        return false;
    }
    // Try to parse as f64, extracting leading numeric portion
    // "1x" → 1.0, "0.5abc" → 0.5, "abc" → 0.0
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return false;
    }
    // Find the longest numeric prefix
    let mut end = 0;
    let mut has_dot = false;
    let mut has_digit = false;
    let chars: Vec<char> = trimmed.chars().collect();

    // Handle optional leading sign
    if !chars.is_empty() && (chars[0] == '-' || chars[0] == '+') {
        end = 1;
    }

    while end < chars.len() {
        let c = chars[end];
        if c.is_ascii_digit() {
            has_digit = true;
            end += 1;
        } else if c == '.' && !has_dot {
            has_dot = true;
            end += 1;
        } else {
            break;
        }
    }

    if !has_digit {
        return false;
    }

    // Parse the numeric prefix
    let num_str: String = chars[..end].iter().collect();
    match num_str.parse::<f64>() {
        Ok(n) => n != 0.0,
        Err(_) => false,
    }
}

