        return Some(Instruction::Copy { dest, src: *lhs });
    }
    // Reassociation: (x | C1) | C2 => x | (C1 | C2)
    if let Some(inst) = try_reassociate_bitwise(dest, IrBinOp::Or, lhs, rhs, ty, binop_defs) {
