        // Check for UNION ALL vs UNION
        let saved = self.position;
        self.consume_keyword(Keyword::Union)?;
        let all = self.peek_keyword(Keyword::All);
        self.position = saved; // restore position
        if all {
            Some("UNION ALL")
        } else {
